const route = $('Loop Routes').item.json;
const stats = $input.item.json;

const price = parseFloat(route.price);
const allTimeLow = stats.all_time_low != null ? parseFloat(stats.all_time_low) : null;
const avg30d = stats.avg_30d != null ? parseFloat(stats.avg_30d) : null;

let alertType = null;
let oldLow = allTimeLow;
let pctBelow = null;

if (allTimeLow !== null && price < allTimeLow) {
  alertType = 'new_low';
}

if (avg30d !== null && price < avg30d * 0.8) {
  pctBelow = Math.round((1 - price / avg30d) * 100);
  if (!alertType) alertType = 'significant_drop';
}

return [{
  json: {
    destination_iata: route.destination_iata,
    destination_name: route.destination_name,
    departure_date: route.departure_date,
    price: price,
    stops: route.stops,
    layover_airport: route.layover_airport,
    flight_duration: route.flight_duration,
    all_time_low: allTimeLow,
    avg_30d: avg30d ? Math.round(avg30d) : null,
    alert_type: alertType,
    pct_below: pctBelow
  }
}];

const allItems = $('Evaluate Alert').all();
const alerts = allItems.filter(item => item.json.alert_type !== null);

if (alerts.length === 0) {
  return [{ json: { hasAlerts: false, alerts: [], count: 0 } }];
}

return [{ json: { hasAlerts: true, alerts: alerts.map(a => a.json), count: alerts.length } }];

const data = $input.item.json;
if (!data.hasAlerts || data.alerts.length === 0) {
  return [{ json: { skip: true } }];
}

const alerts = data.alerts;
const today = new Date().toISOString().split('T')[0];

const messages = [];
let current = `✈️ **FlightCheck** — ${alerts.length} deal${alerts.length > 1 ? 's' : ''} found (${today})\n`;

for (const a of alerts) {
  let line = '';
  if (a.alert_type === 'new_low') {
    line = `🔴 NEW LOW  ALB→${a.destination_name} (${a.destination_iata})  **$${a.price}**  prev low $${a.all_time_low || 'n/a'}  via ${a.layover_airport || 'direct'}`;
  } else {
    line = `📉 -${a.pct_below}%    ALB→${a.destination_name} (${a.destination_iata})  **$${a.price}**  30d avg $${a.avg_30d || 'n/a'}   via ${a.layover_airport || 'direct'}`;
  }
  if (a.alert_type === 'new_low' && a.pct_below) {
    line += ` (${a.pct_below}% below 30d avg)`;
  }

  if ((current + '\n' + line).length > 1800) {
    messages.push(current);
    current = line;
  } else {
    current += '\n' + line;
  }
}
messages.push(current);

return messages.map(m => ({ json: { content: m } }));
